# Expected values are SymPy's outputs for the same calls (Lie algebras). SymPy returns
# Python floats for some Weyl group orders and bases (6.0); those compare as numbers.

skip_unless_full_tests()

fmt <- function(r) {
  if (inherits(r, "symmatrix")) {
    rows <- lapply(seq_len(r$nrow), function(i) paste0("[", paste(vapply(seq_len(r$ncol), function(j) sstr(.mget(r, i, j)), ""), collapse = ", "), "]"))
    return(paste0("Matrix([", paste(rows, collapse = ", "), "])"))
  }
  if (is_sym(r)) return(sstr(r))
  if (is.list(r) && !is.null(names(r))) return(paste0("{", paste(paste0(names(r), ": ", vapply(r, fmt, "")), collapse = ", "), "}"))
  if (is.list(r)) return(paste0("[", paste(vapply(r, fmt, ""), collapse = ", "), "]"))
  if (is.character(r) && length(r) == 1L) return(gsub("\n", "\\n", r, fixed = TRUE))
  if (is.character(r)) return(paste0("[", paste(r, collapse = ", "), "]"))
  if (is.numeric(r)) return(format(r, scientific = FALSE))
  format(r)
}

test_that("Lie algebras match SymPy", {
  expect_equal(fmt(cartan_rank(CartanType("A2"))), "2")
  expect_equal(fmt(dimension(CartanType("A2"))), "3")
  expect_equal(fmt(roots(CartanType("A2"))), "6")
  expect_equal(fmt(basis(CartanType("A2"))), "3")
  expect_equal(fmt(cartan_matrix(CartanType("A2"))), "Matrix([[2, -1], [-1, 2]])")
  expect_equal(fmt(dynkin_diagram(CartanType("A2"))), "0---0\\n1   2")
  expect_equal(fmt(positive_roots(CartanType("A2"))), "{1: [1, -1, 0], 2: [1, 0, -1], 3: [0, 1, -1]}")
  expect_equal(fmt(simple_root(CartanType("A2"), 1)), "[1, -1, 0]")
  expect_equal(fmt(simple_root(CartanType("A2"), 2)), "[0, 1, -1]")
  expect_equal(fmt(simple_roots(RootSystem("A2"))), "{1: [1, -1, 0], 2: [0, 1, -1]}")
  expect_equal(fmt(all_roots(RootSystem("A2"))), "{1: [1, -1, 0], 2: [1, 0, -1], 3: [0, 1, -1], 4: [-1, 1, 0], 5: [-1, 0, 1], 6: [0, -1, 1]}")
  expect_equal(fmt(root_space(RootSystem("A2"))), "alpha[1] + alpha[2]")
  expect_equal(fmt(add_simple_roots(RootSystem("A2"), 1, 2)), "[1, 0, -1]")
  expect_equal(fmt(generators(WeylGroup("A2"))), "[r1, r2]")
  expect_equal(fmt(group_order(WeylGroup("A2"))), "6")
  expect_equal(fmt(group_name(WeylGroup("A2"))), "S3: the symmetric group acting on 3 elements.")
  expect_equal(fmt(coxeter_diagram(WeylGroup("A2"))), "0---0\\n1   2")
  expect_equal(fmt(matrix_form(WeylGroup("A2"), "r1")), "Matrix([[0, 1, 0], [1, 0, 0], [0, 0, 1]])")
  expect_equal(fmt(element_order(WeylGroup("A2"), "r1")), "2")
  expect_equal(fmt(matrix_form(WeylGroup("A2"), "r1*r2")), "Matrix([[0, 0, 1], [1, 0, 0], [0, 1, 0]])")
  expect_equal(fmt(element_order(WeylGroup("A2"), "r1*r2")), "3")
  expect_equal(fmt(matrix_form(WeylGroup("A2"), "r2*r1*r2")), "Matrix([[0, 0, 1], [0, 1, 0], [1, 0, 0]])")
  expect_equal(fmt(element_order(WeylGroup("A2"), "r2*r1*r2")), "2")
  expect_equal(fmt(matrix_form(WeylGroup("A2"), "r1*r2*r1*r2*r1")), "Matrix([[1, 0, 0], [0, 0, 1], [0, 1, 0]])")
  expect_equal(fmt(element_order(WeylGroup("A2"), "r1*r2*r1*r2*r1")), "2")
  expect_equal(fmt(cartan_rank(CartanType("A3"))), "3")
  expect_equal(fmt(dimension(CartanType("A3"))), "4")
  expect_equal(fmt(roots(CartanType("A3"))), "12")
  expect_equal(fmt(basis(CartanType("A3"))), "8")
  expect_equal(fmt(cartan_matrix(CartanType("A3"))), "Matrix([[2, -1, 0], [-1, 2, -1], [0, -1, 2]])")
