  expect_equal(fmt(positive_roots(CartanType("A3"))), "{1: [1, -1, 0, 0], 2: [1, 0, -1, 0], 3: [1, 0, 0, -1], 4: [0, 1, -1, 0], 5: [0, 1, 0, -1], 6: [0, 0, 1, -1]}")
  expect_equal(fmt(simple_root(CartanType("A3"), 1)), "[1, -1, 0, 0]")
  expect_equal(fmt(simple_root(CartanType("A3"), 2)), "[0, 1, -1, 0]")
  expect_equal(fmt(simple_root(CartanType("A3"), 3)), "[0, 0, 1, -1]")
  expect_equal(fmt(simple_roots(RootSystem("A3"))), "{1: [1, -1, 0, 0], 2: [0, 1, -1, 0], 3: [0, 0, 1, -1]}")
