  expect_equal(fmt(all_roots(RootSystem("A4"))), "{1: [1, -1, 0, 0, 0], 2: [1, 0, -1, 0, 0], 3: [1, 0, 0, -1, 0], 4: [1, 0, 0, 0, -1], 5: [0, 1, -1, 0, 0], 6: [0, 1, 0, -1, 0], 7: [0, 1, 0, 0, -1], 8: [0, 0, 1, -1, 0], 9: [0, 0, 1, 0, -1], 10: [0, 0, 0, 1, -1], 11: [-1, 1, 0, 0, 0], 12: [-1, 0, 1, 0, 0], 13: [-1, 0, 0, 1, 0], 14: [-1, 0, 0, 0, 1], 15: [0, -1, 1, 0, 0], 16: [0, -1, 0, 1, 0], 17: [0, -1, 0, 0, 1], 18: [0, 0, -1, 1, 0], 19: [0, 0, -1, 0, 1], 20: [0, 0, 0, -1, 1]}")
